import{_ as t,o as a,c as r,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const g=JSON.parse('{"title":"第 13 章 知识管理：让记忆可复用（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第13章 知识管理：让记忆可复用（易懂版）.md","filePath":"easy/第13章 知识管理：让记忆可复用（易懂版）.md"}'),s={name:"easy/第13章 知识管理：让记忆可复用（易懂版）.md"};function n(l,o,i,u,d,h){return a(),r("div",null,[...o[0]||(o[0]=[e('<h1 id="第-13-章-知识管理-让记忆可复用-易懂版" tabindex="-1">第 13 章 知识管理：让记忆可复用（易懂版） <a class="header-anchor" href="#第-13-章-知识管理-让记忆可复用-易懂版" aria-label="Permalink to &quot;第 13 章 知识管理：让记忆可复用（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 [第 13 章 知识管理：让记忆可复用（完整版）](../../bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 13 章 知识管理：让记忆可复用.md)。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>把散落的资料变成&quot;随取随用&quot;的宝库——让知识不只是收藏，而是能复用。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>有人收藏了 1000 篇文章，但要用时一篇也找不到；有人只存 20 篇，但分类清楚、每篇有笔记——<strong>后者才是真会管知识</strong>。</p><p>知识管理不是&quot;存得多&quot;，而是&quot;<strong>找得到、用得上</strong>&quot;。</p><h2 id="核心就-3-件事" tabindex="-1">核心就 3 件事 <a class="header-anchor" href="#核心就-3-件事" aria-label="Permalink to &quot;核心就 3 件事&quot;">​</a></h2><ol><li><strong>先建分类再存东西</strong>：按你的工作建 3-5 个大类（如：周报、方案、学习笔记、合同），每类一个文件夹。</li><li><strong>命名即检索</strong>：文件名把关键信息带上——<code>2026-08-01-周报-市场部.md</code> 一看就懂，搜索也快。</li><li><strong>每篇留个&quot;摘要&quot;</strong>：重要文档开头写 3 行&quot;这是什么、核心结论、什么时候用&quot;——<strong>下次 10 秒想起它</strong>。</li></ol><h2 id="我的角色是什么" tabindex="-1">我的角色是什么？ <a class="header-anchor" href="#我的角色是什么" aria-label="Permalink to &quot;我的角色是什么？&quot;">​</a></h2><p>我不是知识库本身，而是你的<strong>知识管家</strong>：</p><ul><li>帮你在资料堆里<strong>找</strong>（&quot;上次那个改价方案在哪？&quot;）；</li><li>帮你把资料<strong>归类</strong>（&quot;按项目分一下&quot;）；</li><li>帮你把散内容<strong>沉淀</strong>成结构化笔记；</li><li>配合记忆系统，<strong>跨对话记得</strong>你知识库的格局。</li></ul><h2 id="上手小例子" tabindex="-1">上手小例子 <a class="header-anchor" href="#上手小例子" aria-label="Permalink to &quot;上手小例子&quot;">​</a></h2><blockquote><p><strong>指令</strong>：&quot;帮我把 <code>资料</code> 文件夹按 周报/方案/合同 三类整理，文件名统一改成 <code>日期-类型-标题</code>，每份开头加三行摘要。&quot;</p><p><strong>你会看到</strong>：我列整理方案 → 批量改名归类 → 给每份写摘要 → 交付整理报告。</p></blockquote><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 只存不用——<strong>知识库的价值在&quot;复用&quot;</strong>；</li><li>❌ 分类太细——<strong>超过 7 个大类，就分不动了</strong>；</li><li>❌ 存了不管——<strong>定期(每月)清理一次，删掉过期的</strong>。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>知识管理 = 少而精的归类 + 看得懂的命名 + 三行摘要。</strong> 存进去是为了拿出来。</p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>选一个最乱的资料文件夹——<strong>它能不能用&quot;类型+日期&quot;重新命名？</strong> 能，就从它开始。</p><p>👉 [下一章：资讯与信息流，收集、筛选、汇总（易懂版）](第14章 资讯与信息流：收集、筛选、汇总（易懂版）.md)</p>',21)])])}const q=t(s,[["render",n]]);export{g as __pageData,q as default};
